// Actual unchanged UnordItems::{all,any}, independently overridden iterator
// methods, and real Fn/FnMut/FnOnce cells with compiler-generated field glue.
#![feature(fn_traits,unboxed_closures,try_trait_v2,panic_can_unwind,panic_internals)]
#![allow(internal_features)]
use rustc_data_structures::unord::UnordItems;
use std::{cell::Cell,io::{self,Write},ops::{Try,ControlFlow},panic::{self,AssertUnwindSafe,catch_unwind}};
#[derive(Clone,Copy)]struct Config{length:usize,stop:u64,next_fail:isize,call_fail:isize,item_fail:i64,env_fail:bool,token_fail:bool,iterator_fail:bool,resume:bool}
thread_local!{static CONFIG:Cell<Config>=const{Cell::new(Config{length:0,stop:0,next_fail:-1,call_fail:-1,item_fail:-1,env_fail:false,token_fail:false,iterator_fail:false,resume:false})};}
fn event(s:impl AsRef<str>){println!("{}",s.as_ref());io::stdout().flush().unwrap();}fn hex(s:&str)->String{s.bytes().map(|b|format!("{b:02x}")).collect()}
#[track_caller]fn raise(s:&'static str)->!{if CONFIG.get().resume{panic::resume_unwind(Box::new(s))}else{panic::panic_any(s)}}
struct Value(u64);impl Drop for Value{fn drop(&mut self){event(format!("item:{}:{}",self.0,std::thread::panicking()));if self.0 as i64==CONFIG.get().item_fail{raise("item_drop")}}}
struct Token;impl Drop for Token{fn drop(&mut self){event(format!("token:{}",std::thread::panicking()));if CONFIG.get().token_fail{raise("token_drop")}}}
struct Function{calls:Cell<usize>,_token:Token}
impl Drop for Function{fn drop(&mut self){event(format!("function:{}:{}",self.calls.get(),std::thread::panicking()));if CONFIG.get().env_fail{raise("function_drop")}}}
impl Function{fn body(&self,x:&Value,which:&str)->bool{let call=self.calls.get();self.calls.set(call+1);event(format!("{which}:{call}:{}:{}",x.0,std::thread::panicking()));if call as isize==CONFIG.get().call_fail{raise("call")};x.0!=CONFIG.get().stop}}
impl FnOnce<(Value,)> for Function{type Output=bool;extern "rust-call" fn call_once(self,(x,):(Value,))->bool{self.body(&x,"once")}}
impl FnMut<(Value,)> for Function{extern "rust-call" fn call_mut(&mut self,(x,):(Value,))->bool{self.body(&x,"mut")}}
impl Fn<(Value,)> for Function{extern "rust-call" fn call(&self,(x,):(Value,))->bool{self.body(&x,"shared")}}
struct Input{next:usize}
impl Drop for Input{fn drop(&mut self){event(format!("iterator:{}:{}",self.next,std::thread::panicking()));if CONFIG.get().iterator_fail{raise("iterator_drop")}}}
impl Iterator for Input{type Item=Value;fn next(&mut self)->Option<Value>{let n=self.next;self.next+=1;event(format!("next:{n}:{}",std::thread::panicking()));if n as isize==CONFIG.get().next_fail{raise("next")};if n<CONFIG.get().length{Some(Value(n as u64))}else{None}}}
struct TryInput<const MODE:u8>(Input);impl<const MODE:u8> Iterator for TryInput<MODE>{type Item=Value;fn next(&mut self)->Option<Value>{self.0.next()}fn try_fold<B,F,R>(&mut self,mut init:B,mut f:F)->R where F:FnMut(B,Value)->R,R:Try<Output=B>{event("try_fold");if MODE==1{drop(f);event("after_check_drop");return R::from_output(init)}if MODE==2{std::mem::forget(f);event("after_check_forget");return R::from_output(init)}if MODE==3{let Some(value)=self.next()else{return R::from_output(init)};let result=FnOnce::call_once(f,(init,value));event("after_check_once");return result}while let Some(x)=self.next(){match f(init,x).branch(){ControlFlow::Continue(value)=>init=value,ControlFlow::Break(residual)=>return R::from_residual(residual)}}R::from_output(init)}}
struct Override(Input);impl Iterator for Override{type Item=Value;fn next(&mut self)->Option<Value>{self.0.next()}fn all<F:FnMut(Value)->bool>(&mut self,mut f:F)->bool{event("all_override");f(Value(99))}fn any<F:FnMut(Value)->bool>(&mut self,mut f:F)->bool{event("any_override");f(Value(99))}}
fn execute<I:Iterator<Item=Value>>(input:I,any:bool)->bool{let f=Function{calls:Cell::new(0),_token:Token};if any{UnordItems::new(input).any(f)}else{UnordItems::new(input).all(f)}}
fn message(p:Box<dyn std::any::Any+Send>)->String{p.downcast_ref::<&str>().map(|s|(*s).to_owned()).unwrap_or_else(||"opaque".into())}
fn body(action:usize){event(format!("body:{}",std::thread::panicking()));let result=catch_unwind(AssertUnwindSafe(||{let input=Input{next:0};let value=match action/2{0=>execute(input,action%2==1),1=>execute(TryInput::<0>(input),action%2==1),2=>execute(Override(input),action%2==1),3=>execute(TryInput::<1>(input),action%2==1),4=>execute(TryInput::<2>(input),action%2==1),5=>execute(TryInput::<3>(input),action%2==1),_=>unreachable!()};event(format!("returned:{value}"))}));event(format!("caught:{}:{}",hex(&result.err().map(message).unwrap_or_default()),std::thread::panicking()));}
struct Outer(usize);impl Drop for Outer{fn drop(&mut self){body(self.0)}}
fn main(){let args:Vec<_>=std::env::args().collect();let mode=args[1].clone();let action=args[2].parse::<usize>().unwrap();let n:Vec<i64>=args[3].split(',').map(|v|v.parse().unwrap()).collect();CONFIG.set(Config{length:n[0]as usize,stop:n[1]as u64,next_fail:n[2]as isize,call_fail:n[3]as isize,item_fail:n[4],env_fail:n[5]!=0,token_fail:n[6]!=0,iterator_fail:n[7]!=0,resume:n[8]!=0});let processing=mode=="processing";panic::set_hook(Box::new(move|info|{let payload=info.payload().downcast_ref::<&str>().copied().unwrap_or("");let kind=if info.payload().is::<&str>(){"static_str"}else{"opaque"};let(file,line,column)=info.location().map(|l|(l.file(),l.line(),l.column())).unwrap_or(("",0,0));event(format!("HOOK:{kind}:{}:{}:{}:{}:{}:{line}:{column}",hex(payload),std::thread::panicking(),info.can_unwind(),info.force_no_backtrace(),hex(file)));if processing{body(action)}}));match mode.as_str(){"normal"=>body(action),"unwind"=>{let _=catch_unwind(||{let _outer=Outer(action);panic::panic_any("outer")});event("outer_end:false")},"processing"=>{let _=catch_unwind(||panic::panic_any("outer"));event("outer_end:false")},_=>panic!("mode")}}
